-- Zoológico Vivo · Supabase PostgreSQL + Auth. Ejecutar una vez en SQL Editor.
create table if not exists public.visitantes(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Visitante',first_name text,last_name text,email text,phone text,origin text check(origin in ('Huancayo','Otra provincia de Junín','Otra región del Perú','Extranjero')),location_detail text,age_range text check(age_range in ('Niño','Adolescente','Adulto','Adulto mayor')),referral_source text,created_at timestamptz not null default now());
alter table public.visitantes add column if not exists first_name text,add column if not exists last_name text,add column if not exists email text,add column if not exists phone text,add column if not exists origin text,add column if not exists location_detail text,add column if not exists age_range text,add column if not exists referral_source text;
create table if not exists public.progreso_visitantes(user_id uuid primary key references auth.users(id) on delete cascade,points integer not null default 0 check(points>=0),visited_animals jsonb not null default '[]'::jsonb,correct_answers integer not null default 0,answered_questions integer not null default 0,completed_tours integer not null default 0,updated_at timestamptz not null default now());
create table if not exists public.animales(id uuid primary key default gen_random_uuid(),name text not null unique,species text,description text,foto_url text,datos_ejemplar jsonb not null default '{}'::jsonb,estado_datos text not null default 'Pendiente de actualización',is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.preguntas(id uuid primary key default gen_random_uuid(),animal_id uuid not null references public.animales(id) on delete cascade,pregunta text not null,opcion_a text not null,opcion_b text not null,opcion_c text not null,respuesta_correcta char(1) not null check(respuesta_correcta in ('A','B','C')),retroalimentacion text,question_order smallint,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.visitas_animales(id uuid primary key default gen_random_uuid(),visitor_id uuid not null references auth.users(id) on delete cascade,animal_id uuid not null references public.animales(id),visited_at timestamptz not null default now(),points integer not null default 1,unique(visitor_id,animal_id));
create table if not exists public.respuestas(id uuid primary key default gen_random_uuid(),visitor_id uuid not null references auth.users(id) on delete cascade,question_id uuid not null references public.preguntas(id),is_correct boolean not null,answered_at timestamptz not null default now(),unique(visitor_id,question_id));
alter table public.preguntas add column if not exists question_order smallint;
create table if not exists public.opiniones(id uuid primary key default gen_random_uuid(),visitor_id uuid not null references auth.users(id) on delete cascade,rating integer not null check(rating between 1 and 5),comment text,created_at timestamptz not null default now());
create table if not exists public.reportes(id uuid primary key default gen_random_uuid(),visitor_id uuid not null references auth.users(id) on delete cascade,category text not null,animal_location text,description text not null,photo_url text,status text not null default 'Nuevo' check(status in ('Nuevo','En revisión','Resuelto')),created_at timestamptz not null default now());
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade,role text not null default 'admin' check(role in ('admin','staff')),added_at timestamptz not null default now());
create schema if not exists private;create or replace function private.is_app_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admins a where a.user_id=(select auth.uid())); $$;revoke all on function private.is_app_admin() from public;grant usage on schema private to authenticated;grant execute on function private.is_app_admin() to authenticated;
-- RLS habilitada para todas las tablas con datos.
alter table public.visitantes enable row level security;alter table public.progreso_visitantes enable row level security;alter table public.animales enable row level security;alter table public.preguntas enable row level security;alter table public.visitas_animales enable row level security;alter table public.respuestas enable row level security;alter table public.opiniones enable row level security;alter table public.reportes enable row level security;alter table public.admins enable row level security;
create or replace function public.zv_policy_setup() returns void language plpgsql as $$ begin
 drop policy if exists profile_read on public.visitantes;create policy profile_read on public.visitantes for select to authenticated using(user_id=(select auth.uid()) or (select private.is_app_admin()));
 drop policy if exists profile_insert on public.visitantes;create policy profile_insert on public.visitantes for insert to authenticated with check(user_id=(select auth.uid()));
 drop policy if exists profile_update on public.visitantes;create policy profile_update on public.visitantes for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
 drop policy if exists progress_read on public.progreso_visitantes;create policy progress_read on public.progreso_visitantes for select to authenticated using(user_id=(select auth.uid()) or (select private.is_app_admin()));
 drop policy if exists progress_insert on public.progreso_visitantes;create policy progress_insert on public.progreso_visitantes for insert to authenticated with check(user_id=(select auth.uid()));
 drop policy if exists progress_update on public.progreso_visitantes;create policy progress_update on public.progreso_visitantes for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
 drop policy if exists animals_read on public.animales;create policy animals_read on public.animales for select to authenticated using(is_active or (select private.is_app_admin()));
 drop policy if exists animals_admin on public.animales;create policy animals_admin on public.animales for all to authenticated using((select private.is_app_admin())) with check((select private.is_app_admin()));
 drop policy if exists questions_admin on public.preguntas;create policy questions_admin on public.preguntas for all to authenticated using((select private.is_app_admin())) with check((select private.is_app_admin()));drop policy if exists questions_read_active on public.preguntas;create policy questions_read_active on public.preguntas for select to authenticated using(active=true or (select private.is_app_admin()));
 drop policy if exists visits_owner_admin on public.visitas_animales;create policy visits_owner_admin on public.visitas_animales for all to authenticated using(visitor_id=(select auth.uid()) or (select private.is_app_admin())) with check(visitor_id=(select auth.uid()) or (select private.is_app_admin()));
 drop policy if exists answers_owner_admin on public.respuestas;create policy answers_owner_admin on public.respuestas for all to authenticated using(visitor_id=(select auth.uid()) or (select private.is_app_admin())) with check(visitor_id=(select auth.uid()) or (select private.is_app_admin()));
 drop policy if exists opinions_owner_admin on public.opiniones;create policy opinions_owner_admin on public.opiniones for all to authenticated using(visitor_id=(select auth.uid()) or (select private.is_app_admin())) with check(visitor_id=(select auth.uid()) or (select private.is_app_admin()));
 drop policy if exists reports_owner_admin on public.reportes;drop policy if exists reports_read_owner_admin on public.reportes;create policy reports_read_owner_admin on public.reportes for select to authenticated using(visitor_id=(select auth.uid()) or (select private.is_app_admin()));drop policy if exists reports_insert_owner on public.reportes;create policy reports_insert_owner on public.reportes for insert to authenticated with check(visitor_id=(select auth.uid()));drop policy if exists reports_update_admin on public.reportes;create policy reports_update_admin on public.reportes for update to authenticated using((select private.is_app_admin())) with check((select private.is_app_admin()));
 drop policy if exists admin_read_self on public.admins;create policy admin_read_self on public.admins for select to authenticated using(user_id=(select auth.uid()));
end; $$;select public.zv_policy_setup();drop function public.zv_policy_setup();
grant select,insert,update on public.visitantes to authenticated;revoke all on public.progreso_visitantes from authenticated;grant select on public.progreso_visitantes to authenticated;grant select on public.animales to authenticated;grant insert,update,delete on public.animales,public.preguntas to authenticated;revoke all on public.preguntas from authenticated;grant select(id,animal_id,pregunta,opcion_a,opcion_b,opcion_c,retroalimentacion,question_order,active) on public.preguntas to authenticated;grant insert,update,delete on public.preguntas to authenticated;grant select on public.visitas_animales,public.respuestas to authenticated;grant select,insert on public.opiniones,public.reportes to authenticated;grant update(status) on public.reportes to authenticated;grant select on public.admins to authenticated;
drop view if exists public.admin_player_scores;create view public.admin_player_scores with(security_invoker=true) as select p.user_id,coalesce(nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),p.display_name) display_name,p.origin,p.location_detail,p.age_range,p.created_at,coalesce(g.points,0) points,coalesce(jsonb_array_length(g.visited_animals),0) animals_visited,coalesce(g.correct_answers,0) correct_answers,coalesce(g.answered_questions,0) answered_questions,coalesce(g.completed_tours,0) completed_tours,g.updated_at from public.visitantes p left join public.progreso_visitantes g using(user_id);grant select on public.admin_player_scores to authenticated;
create or replace function public.create_player_rows() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.visitantes(user_id,display_name,first_name,last_name,email,phone,origin,location_detail,age_range,referral_source) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),'Visitante'),new.raw_user_meta_data->>'first',new.raw_user_meta_data->>'last',new.email,new.raw_user_meta_data->>'phone',new.raw_user_meta_data->>'origin',new.raw_user_meta_data->>'location_detail',new.raw_user_meta_data->>'age_range',new.raw_user_meta_data->>'referral_source') on conflict(user_id) do nothing;insert into public.progreso_visitantes(user_id) values(new.id) on conflict(user_id) do nothing;return new;end;$$;drop trigger if exists on_auth_user_created_zv on auth.users;create trigger on_auth_user_created_zv after insert on auth.users for each row execute procedure public.create_player_rows();
create index if not exists animal_visits_date_idx on public.visitas_animales(visited_at);create index if not exists opinions_date_idx on public.opiniones(created_at);create index if not exists reports_status_idx on public.reportes(status);create index if not exists questions_animal_idx on public.preguntas(animal_id);
-- Fichas educativas de ejemplo; el inventario y datos de ejemplares requieren confirmación oficial.
alter table public.animales add column if not exists slug text;alter table public.animales add column if not exists food text;alter table public.animales add column if not exists habitat text;alter table public.animales add column if not exists fact text;
create unique index if not exists animals_slug_idx on public.animales(slug) where slug is not null;
insert into public.animales(slug,name,species,description,food,habitat,fact,estado_datos) values
('leon','León','León africano','Ejemplo educativo; datos del ejemplar por validar.','Carnívoro','Sabanas y bosques abiertos','Los leones viven en grupos llamados manadas.','Pendiente de actualización'),
('alpaca','Alpaca','Alpaca','Ejemplo educativo; datos del ejemplar por validar.','Herbívora','Altiplano andino','La alpaca está adaptada a las alturas andinas.','Pendiente de actualización'),
('mono','Mono','Primates','Ejemplo educativo; especie específica por confirmar.','Frutas y otros alimentos','Bosques tropicales','Muchas especies de monos usan las manos para sujetar alimentos.','Pendiente de actualización'),
('oso','Oso de anteojos','Oso de anteojos','Ejemplo educativo; datos del ejemplar por validar.','Omnívoro','Bosques andinos','Es el único oso nativo de Sudamérica.','Pendiente de actualización'),
('venado','Venado','Venado','Ejemplo educativo; especie específica por confirmar.','Herbívoro','Bosques y matorrales','Los venados tienen sentidos agudos para detectar su entorno.','Pendiente de actualización'),
('condor','Cóndor','Cóndor andino','Ejemplo educativo; datos del ejemplar por validar.','Carroñera','Montañas y cañones','El cóndor aprovecha corrientes de aire para planear.','Pendiente de actualización'),
('jirafa','Jirafa','Jirafa','Ejemplo ilustrativo de la maqueta; confirmar si corresponde al inventario.','Herbívora','Sabanas africanas','La jirafa es el animal terrestre más alto.','Pendiente de actualización')
on conflict(name) do update set slug=excluded.slug,species=excluded.species,description=excluded.description,food=excluded.food,habitat=excluded.habitat,fact=excluded.fact;
create unique index if not exists questions_animal_prompt_unique on public.preguntas(animal_id,pregunta);
with q as (select a.id animal_id,a.name,a.habitat,a.food,a.fact from public.animales a where a.slug in ('leon','alpaca','mono','oso','venado','condor','jirafa'))
insert into public.preguntas(animal_id,pregunta,opcion_a,opcion_b,opcion_c,respuesta_correcta,retroalimentacion,question_order)
select q.animal_id,x.pregunta,x.a,x.b,x.c,'A',x.feedback,x.ord from q cross join lateral(values
(1,'¿Qué dato describe al '||q.name||'? ',q.fact,'Vive siempre bajo el agua','No necesita alimento','Dato educativo: '||q.fact),
(2,'¿Qué alimentación corresponde al '||q.name||'? ',q.food,'Solo piedras','Solo agua','Su alimentación general es '||q.food||'.'),
(3,'¿Cuál es el hábitat general del '||q.name||'? ',q.habitat,'El océano polar','Un arrecife coralino','Su hábitat general es '||q.habitat||'.')
) as x(ord,pregunta,a,b,c,feedback) on conflict(animal_id,pregunta) do nothing;

create unique index if not exists answers_user_question_idx on public.respuestas(visitor_id,question_id);
create unique index if not exists questions_animal_order_idx on public.preguntas(animal_id,question_order);
create or replace function public.zv_record_visit(p_animal_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare uid uuid := (select auth.uid()); n integer; slug_value text; begin if uid is null then raise exception 'authentication required'; end if; select slug into slug_value from public.animales where id=p_animal_id and is_active; if slug_value is null then raise exception 'animal unavailable'; end if; insert into public.visitas_animales(visitor_id,animal_id,points) values(uid,p_animal_id,1) on conflict(visitor_id,animal_id) do nothing; get diagnostics n = row_count; if n=1 then insert into public.progreso_visitantes(user_id) values(uid) on conflict(user_id) do nothing; update public.progreso_visitantes set points=points+1,visited_animals=case when visited_animals ? slug_value then visited_animals else visited_animals || jsonb_build_array(slug_value) end,updated_at=now() where user_id=uid; return true; end if; return false; end; $$;
create or replace function public.zv_submit_answer(p_question_id uuid,p_option char) returns jsonb language plpgsql security definer set search_path='' as $$ declare uid uuid := (select auth.uid()); correct char(1); is_right boolean; n integer; begin if uid is null then raise exception 'authentication required'; end if; select q.respuesta_correcta into correct from public.preguntas q join public.animales a on a.id=q.animal_id where q.id=p_question_id and q.active and a.is_active; if correct is null then raise exception 'question unavailable'; end if; is_right := upper(p_option)=correct; insert into public.respuestas(visitor_id,question_id,is_correct) values(uid,p_question_id,is_right) on conflict(visitor_id,question_id) do nothing; get diagnostics n = row_count; if n=1 then insert into public.progreso_visitantes(user_id) values(uid) on conflict(user_id) do nothing; update public.progreso_visitantes set answered_questions=answered_questions+1,correct_answers=correct_answers+(case when is_right then 1 else 0 end),points=points+(case when is_right then 1 else 0 end),updated_at=now() where user_id=uid; end if; return jsonb_build_object('is_correct',is_right,'already_answered',n=0); end; $$;
revoke all on function public.zv_record_visit(uuid) from public;revoke all on function public.zv_submit_answer(uuid,char) from public;grant execute on function public.zv_record_visit(uuid) to authenticated;grant execute on function public.zv_submit_answer(uuid,char) to authenticated;

create or replace function public.zv_finish_tour() returns void language plpgsql security definer set search_path='' as $$ declare uid uuid := (select auth.uid()); begin if uid is null then raise exception 'authentication required'; end if; insert into public.progreso_visitantes(user_id) values(uid) on conflict(user_id) do nothing; update public.progreso_visitantes set completed_tours=completed_tours+1,updated_at=now() where user_id=uid; end; $$;revoke all on function public.zv_finish_tour() from public;grant execute on function public.zv_finish_tour() to authenticated;
